-- Publish T Level Week 7 exercises into the marking catalogue as 0.4.47.
-- Starts from the current published package so Weeks 1-6 stay available.
-- Replaces only Week 7 activities. Does not retire prior versions or attempts.

do $$
declare
  v_package jsonb;
  v_new_activities jsonb := $w7act$[{"schema":"lp.content.activity","schemaVersion":"0.1.0","id":"week-7-lesson-1-ex-01","version":"0.1.0","metadata":{"title":"Why draw the process?","status":"available","summary":"A process diagram shows steps and decisions before anyone builds screens.","href":null,"difficulty":"standard","familyId":"week-7-lesson-1-ex-01","estimatedDurationMinutes":3,"activityType":"Single choice","topics":["Process diagrams"],"detail":"A process diagram shows steps and decisions before anyone builds screens."},"relationships":{"learningOutcomes":["lo1","w7-process-erd","w7-interface-algo","w7-data"],"assignment":"os-formative","questions":[],"assets":[],"prerequisites":[]},"blocks":[{"schema":"lp.content.block","schemaVersion":"0.1.0","id":"week-7-lesson-1-ex-01-purpose","version":"0.1.0","metadata":{},"relationships":{},"type":"single-choice","content":{"formative":true,"questionId":"week-7-lesson-1-ex-01:purpose","sourceQuestionId":"purpose","sourceType":"single","prompt":"Oakfield wants learners to request a place on a published course. Why draw a process diagram first?","options":[{"id":"a","label":"To list the entities, keys and relationships instead of the steps"},{"id":"b","label":"To show the order of steps, the capacity decision and both outcomes"},{"id":"c","label":"To settle the button labels and colours before the steps are known"},{"id":"d","label":"To replace the ERD, because the flowchart will store the records"}],"correctOptionId":"b","feedback":{"correct":"A process diagram shows what happens, in what order, and which choice is made. Entities and keys belong on the ERD.","incorrect":"An ERD stores data. A wireframe shows the screen. Neither replaces the steps."}}}]},{"schema":"lp.content.activity","schemaVersion":"0.1.0","id":"week-7-lesson-1-ex-02","version":"0.1.0","metadata":{"title":"Flowchart symbols","status":"available","summary":"Match each symbol to the job it does in a flowchart.","href":null,"difficulty":"standard","familyId":"week-7-lesson-1-ex-02","estimatedDurationMinutes":4,"activityType":"Matching","topics":["Flowchart symbols"],"detail":"Match each symbol to the job it does in a flowchart."},"relationships":{"learningOutcomes":["lo1","w7-process-erd","w7-interface-algo","w7-data"],"assignment":"os-formative","questions":[],"assets":[],"prerequisites":[]},"blocks":[{"schema":"lp.content.block","schemaVersion":"0.1.0","id":"week-7-lesson-1-ex-02-symbols","version":"0.1.0","metadata":{},"relationships":{},"type":"drag-drop","content":{"formative":true,"questionId":"week-7-lesson-1-ex-02:symbols","sourceQuestionId":"symbols","prompt":"Match each flowchart symbol to its meaning.","items":[{"id":"term","label":"Oval (terminator)"},{"id":"proc","label":"Rectangle"},{"id":"dec","label":"Diamond"},{"id":"io","label":"Parallelogram"}],"targets":[{"id":"m-term","label":"Start or end of the process"},{"id":"m-proc","label":"A step that is carried out"},{"id":"m-dec","label":"A question with more than one path"},{"id":"m-io","label":"Data that is entered or a message that is shown"}],"correct":{"term":"m-term","proc":"m-proc","dec":"m-dec","io":"m-io"},"feedback":{"correct":"Ovals start and finish. Rectangles are actions. Diamonds are decisions. Parallelograms are inputs or outputs.","incorrect":"A diamond is a question, not the start of the diagram."}}}]},{"schema":"lp.content.activity","schemaVersion":"0.1.0","id":"week-7-lesson-1-ex-03","version":"0.1.0","metadata":{"title":"Put the request in order","status":"available","summary":"The sequence has to match how a booking actually happens.","href":null,"difficulty":"standard","familyId":"week-7-lesson-1-ex-03","estimatedDurationMinutes":3,"activityType":"Single choice","topics":["Process sequence"],"detail":"The sequence has to match how a booking actually happens."},"relationships":{"learningOutcomes":["lo1","w7-process-erd","w7-interface-algo","w7-data"],"assignment":"os-formative","questions":[],"assets":[],"prerequisites":[]},"blocks":[{"schema":"lp.content.block","schemaVersion":"0.1.0","id":"week-7-lesson-1-ex-03-order","version":"0.1.0","metadata":{},"relationships":{},"type":"single-choice","content":{"formative":true,"questionId":"week-7-lesson-1-ex-03:order","sourceQuestionId":"order","sourceType":"single","prompt":"Which order best describes Oakfield's 'request a place' process?","options":[{"id":"a","label":"Confirm the booking, then ask which course was chosen, then check places"},{"id":"b","label":"Check places on every course, then ask the learner which course they meant"},{"id":"c","label":"The learner chooses a published course, submits the request, the system checks places, then confirms the booking or says the course is full"},{"id":"d","label":"Store an attendance mark, then create the session, then create the course"}],"correctOptionId":"c","feedback":{"correct":"Choose the course, take the request, check capacity, then give one result.","incorrect":"Do not confirm a place before the course is known, and do not mark attendance for a session that has not been chosen."}}}]},{"schema":"lp.content.activity","schemaVersion":"0.1.0","id":"week-7-lesson-1-ex-04","version":"0.1.0","metadata":{"title":"A decision creates two paths","status":"available","summary":"The capacity check is a decision, not a single happy path.","href":null,"difficulty":"standard","familyId":"week-7-lesson-1-ex-04","estimatedDurationMinutes":3,"activityType":"Single choice","topics":["Decisions"],"detail":"The capacity check is a decision, not a single happy path."},"relationships":{"learningOutcomes":["lo1","w7-process-erd","w7-interface-algo","w7-data"],"assignment":"os-formative","questions":[],"assets":[],"prerequisites":[]},"blocks":[{"schema":"lp.content.block","schemaVersion":"0.1.0","id":"week-7-lesson-1-ex-04-paths","version":"0.1.0","metadata":{},"relationships":{},"type":"single-choice","content":{"formative":true,"questionId":"week-7-lesson-1-ex-04:paths","sourceQuestionId":"paths","sourceType":"single","prompt":"A diamond asks 'Are there places left on this course?'. What should the diagram show next?","options":[{"id":"a","label":"Both paths store a Booking, one as Confirmed and one as Full"},{"id":"b","label":"One path that always stores Confirmed. The diamond is only a comment"},{"id":"c","label":"Two paths: store a confirmed booking, or show that the course is full and do not store a booking"},{"id":"d","label":"A new Course row for every learner who is turned away"}],"correctOptionId":"c","feedback":{"correct":"Write both paths. Only the 'places left' path stores a confirmed booking. Course full is a message, not a booking status.","incorrect":"Storing a Full booking, or always storing Confirmed, breaks the capacity rule."}}}]},{"schema":"lp.content.activity","schemaVersion":"0.1.0","id":"week-7-lesson-1-ex-05","version":"0.1.0","metadata":{"title":"Steps that do not belong","status":"available","summary":"Sort steps for the request-a-place flowchart.","href":null,"difficulty":"standard","familyId":"week-7-lesson-1-ex-05","estimatedDurationMinutes":5,"activityType":"Classification","topics":["Process checks"],"detail":"Sort steps for the request-a-place flowchart."},"relationships":{"learningOutcomes":["lo1","w7-process-erd","w7-interface-algo","w7-data"],"assignment":"os-formative","questions":[],"assets":[],"prerequisites":[]},"blocks":[{"schema":"lp.content.block","schemaVersion":"0.1.0","id":"week-7-lesson-1-ex-05-steps","version":"0.1.0","metadata":{},"relationships":{},"type":"classification","content":{"formative":true,"questionId":"week-7-lesson-1-ex-05:steps","sourceQuestionId":"steps","prompt":"Classify each step for Oakfield increment 1, where card payments are out of scope.","categories":[{"id":"belongs","label":"Belongs in request-a-place"},{"id":"missing","label":"Often missing, but needed"},{"id":"out","label":"Does not belong in this process"}],"items":[{"id":"item-1","label":"Learner chooses a published course","correctCategoryId":"belongs"},{"id":"item-2","label":"System checks how many places remain","correctCategoryId":"belongs"},{"id":"item-3","label":"Take a card payment before the request is accepted","correctCategoryId":"out"},{"id":"item-4","label":"A diagram goes from 'request received' straight to End, and never shows confirmed or full","correctCategoryId":"missing"},{"id":"item-5","label":"Mark who attended today's classroom session","correctCategoryId":"out"}],"feedback":{"correct":"Request-a-place needs the course, the capacity check and a result. Item 4 is a required result that the diagram has left out. Card payment is out of scope. Attendance is a later process.","incorrect":"Do not put 'tell the learner the result' in 'does not belong'. The weak diagram is missing that step."}}}]},{"schema":"lp.content.activity","schemaVersion":"0.1.0","id":"week-7-lesson-1-ex-06","version":"0.1.0","metadata":{"title":"Spot the entities","status":"available","summary":"An entity is something the system needs to store as its own set of records.","href":null,"difficulty":"standard","familyId":"week-7-lesson-1-ex-06","estimatedDurationMinutes":4,"activityType":"Classification","topics":["Entities"],"detail":"An entity is something the system needs to store as its own set of records."},"relationships":{"learningOutcomes":["lo1","w7-process-erd","w7-interface-algo","w7-data"],"assignment":"os-formative","questions":[],"assets":[],"prerequisites":[]},"blocks":[{"schema":"lp.content.block","schemaVersion":"0.1.0","id":"week-7-lesson-1-ex-06-entities","version":"0.1.0","metadata":{},"relationships":{},"type":"classification","content":{"formative":true,"questionId":"week-7-lesson-1-ex-06:entities","sourceQuestionId":"entities","prompt":"Classify each item for the Oakfield booking design.","categories":[{"id":"entity","label":"Entity"},{"id":"attr","label":"Attribute, not an entity"},{"id":"neither","label":"Not part of this data model"}],"items":[{"id":"item-1","label":"Learner","correctCategoryId":"entity"},{"id":"item-2","label":"Course","correctCategoryId":"entity"},{"id":"item-3","label":"Email address","correctCategoryId":"attr"},{"id":"item-4","label":"Session","correctCategoryId":"entity"},{"id":"item-5","label":"The shared spreadsheet staff use today","correctCategoryId":"neither"}],"feedback":{"correct":"Learner, Course and Session are entities. Email describes a learner. The spreadsheet is the current tool, not an entity in the new model.","incorrect":"Do not make a separate entity for every field, and do not model the old spreadsheet as a table."}}}]},{"schema":"lp.content.activity","schemaVersion":"0.1.0","id":"week-7-lesson-1-ex-07","version":"0.1.0","metadata":{"title":"Attributes sit on an entity","status":"available","summary":"Say which entity an attribute belongs to.","href":null,"difficulty":"standard","familyId":"week-7-lesson-1-ex-07","estimatedDurationMinutes":4,"activityType":"Classification","topics":["Attributes"],"detail":"Say which entity an attribute belongs to."},"relationships":{"learningOutcomes":["lo1","w7-process-erd","w7-interface-algo","w7-data"],"assignment":"os-formative","questions":[],"assets":[],"prerequisites":[]},"blocks":[{"schema":"lp.content.block","schemaVersion":"0.1.0","id":"week-7-lesson-1-ex-07-attrs","version":"0.1.0","metadata":{},"relationships":{},"type":"classification","content":{"formative":true,"questionId":"week-7-lesson-1-ex-07:attrs","sourceQuestionId":"attrs","prompt":"Where should each fact be stored?","categories":[{"id":"learner","label":"Learner"},{"id":"course","label":"Course"},{"id":"booking","label":"Booking"},{"id":"skip","label":"Do not store"}],"items":[{"id":"item-1","label":"Surname","correctCategoryId":"learner"},{"id":"item-2","label":"Course title","correctCategoryId":"course"},{"id":"item-3","label":"Date the place was requested","correctCategoryId":"booking"},{"id":"item-4","label":"Booking status, Confirmed or Cancelled","correctCategoryId":"booking"},{"id":"item-5","label":"Course title copied again onto every Booking row","correctCategoryId":"skip"}],"feedback":{"correct":"Surname describes the learner. Title and the request date sit on Course and Booking. Status on a stored booking is Confirmed or Cancelled. Course full is a message, not a status.","incorrect":"If Booking stores courseId, copying the title onto Booking duplicates Course."}}}]},{"schema":"lp.content.activity","schemaVersion":"0.1.0","id":"week-7-lesson-1-ex-08","version":"0.1.0","metadata":{"title":"Choose a primary key","status":"available","summary":"A primary key identifies one row and does not repeat for that entity.","href":null,"difficulty":"standard","familyId":"week-7-lesson-1-ex-08","estimatedDurationMinutes":3,"activityType":"Single choice","topics":["Primary keys"],"detail":"A primary key identifies one row and does not repeat for that entity."},"relationships":{"learningOutcomes":["lo1","w7-process-erd","w7-interface-algo","w7-data"],"assignment":"os-formative","questions":[],"assets":[],"prerequisites":[]},"blocks":[{"schema":"lp.content.block","schemaVersion":"0.1.0","id":"week-7-lesson-1-ex-08-pk","version":"0.1.0","metadata":{},"relationships":{},"type":"single-choice","content":{"formative":true,"questionId":"week-7-lesson-1-ex-08:pk","sourceQuestionId":"pk","sourceType":"single","prompt":"Which field should be the primary key of Booking?","options":[{"id":"a","label":"status"},{"id":"b","label":"course title"},{"id":"c","label":"bookingId"},{"id":"d","label":"learner surname"}],"correctOptionId":"c","feedback":{"correct":"bookingId identifies one booking. Status, course title and surname can repeat, so none of them can be the primary key.","incorrect":"A primary key must be unique for that entity. A foreign key such as courseId points elsewhere. It does not identify the booking."}}}]},{"schema":"lp.content.activity","schemaVersion":"0.1.0","id":"week-7-lesson-1-ex-09","version":"0.1.0","metadata":{"title":"What a foreign key does","status":"available","summary":"A foreign key points at a primary key in another entity.","href":null,"difficulty":"standard","familyId":"week-7-lesson-1-ex-09","estimatedDurationMinutes":3,"activityType":"Single choice","topics":["Foreign keys"],"detail":"A foreign key points at a primary key in another entity."},"relationships":{"learningOutcomes":["lo1","w7-process-erd","w7-interface-algo","w7-data"],"assignment":"os-formative","questions":[],"assets":[],"prerequisites":[]},"blocks":[{"schema":"lp.content.block","schemaVersion":"0.1.0","id":"week-7-lesson-1-ex-09-fk","version":"0.1.0","metadata":{},"relationships":{},"type":"single-choice","content":{"formative":true,"questionId":"week-7-lesson-1-ex-09:fk","sourceQuestionId":"fk","sourceType":"single","prompt":"Session stores courseId. Why is courseId a foreign key?","options":[{"id":"a","label":"It is the primary key of Session, so the session number is also the course number"},{"id":"b","label":"It stores the session date in a second format"},{"id":"c","label":"It points at Course.courseId, so each session belongs to one course"},{"id":"d","label":"It means Course can be removed, because the id now lives on Session"}],"correctOptionId":"c","feedback":{"correct":"courseId on Session references Course. That is what makes the relationship one course to many sessions.","incorrect":"A foreign key does not replace the other entity, and it is not the primary key of Session."}}}]},{"schema":"lp.content.activity","schemaVersion":"0.1.0","id":"week-7-lesson-1-ex-10","version":"0.1.0","metadata":{"title":"One-to-one","status":"available","summary":"Use one-to-one only when each side has at most one match.","href":null,"difficulty":"standard","familyId":"week-7-lesson-1-ex-10","estimatedDurationMinutes":3,"activityType":"Single choice","topics":["Cardinality"],"detail":"Use one-to-one only when each side has at most one match."},"relationships":{"learningOutcomes":["lo1","w7-process-erd","w7-interface-algo","w7-data"],"assignment":"os-formative","questions":[],"assets":[],"prerequisites":[]},"blocks":[{"schema":"lp.content.block","schemaVersion":"0.1.0","id":"week-7-lesson-1-ex-10-one","version":"0.1.0","metadata":{},"relationships":{},"type":"single-choice","content":{"formative":true,"questionId":"week-7-lesson-1-ex-10:one","sourceQuestionId":"one","sourceType":"single","prompt":"Which description is one-to-one?","options":[{"id":"a","label":"One course has many sessions"},{"id":"b","label":"One learner can have many bookings"},{"id":"c","label":"One booking has one confirmation code, and that code is not used on another booking"},{"id":"d","label":"Many learners can attend many sessions"}],"correctOptionId":"c","feedback":{"correct":"One confirmation code belongs to one booking, and that booking has one code. Store the code on Booking. Do not add a sixth entity.","incorrect":"Course to Session and Learner to Booking are one-to-many. Attendance is many-to-many."}}}]},{"schema":"lp.content.activity","schemaVersion":"0.1.0","id":"week-7-lesson-1-ex-11","version":"0.1.0","metadata":{"title":"One-to-many","status":"available","summary":"Read the cardinality from the Oakfield rules, not from a guess.","href":null,"difficulty":"standard","familyId":"week-7-lesson-1-ex-11","estimatedDurationMinutes":3,"activityType":"Single choice","topics":["Cardinality"],"detail":"Read the cardinality from the Oakfield rules, not from a guess."},"relationships":{"learningOutcomes":["lo1","w7-process-erd","w7-interface-algo","w7-data"],"assignment":"os-formative","questions":[],"assets":[],"prerequisites":[]},"blocks":[{"schema":"lp.content.block","schemaVersion":"0.1.0","id":"week-7-lesson-1-ex-11-many","version":"0.1.0","metadata":{},"relationships":{},"type":"single-choice","content":{"formative":true,"questionId":"week-7-lesson-1-ex-11:many","sourceQuestionId":"many","sourceType":"single","prompt":"One course has many sessions. Each session belongs to only one course. What is that relationship?","options":[{"id":"a","label":"One-to-one, because every session has a course"},{"id":"b","label":"One-to-many, from Course to Session"},{"id":"c","label":"Many-to-many, because the hub runs many courses and many sessions"},{"id":"d","label":"One-to-many from Session to Course, so one session can belong to several courses"}],"correctOptionId":"b","feedback":{"correct":"One course, many sessions, each session tied to one course: one-to-many from Course to Session.","incorrect":"Many courses and many sessions in the hub do not make this pair many-to-many. Read the rule for one session."}}}]},{"schema":"lp.content.activity","schemaVersion":"0.1.0","id":"week-7-lesson-1-ex-12","version":"0.1.0","metadata":{"title":"Many-to-many needs a link","status":"available","summary":"Booking stores the link between learners and courses.","href":null,"difficulty":"standard","familyId":"week-7-lesson-1-ex-12","estimatedDurationMinutes":4,"activityType":"Single choice","topics":["Relationships"],"detail":"Booking stores the link between learners and courses."},"relationships":{"learningOutcomes":["lo1","w7-process-erd","w7-interface-algo","w7-data"],"assignment":"os-formative","questions":[],"assets":[],"prerequisites":[]},"blocks":[{"schema":"lp.content.block","schemaVersion":"0.1.0","id":"week-7-lesson-1-ex-12-mm","version":"0.1.0","metadata":{},"relationships":{},"type":"single-choice","content":{"formative":true,"questionId":"week-7-lesson-1-ex-12:mm","sourceQuestionId":"mm","sourceType":"single","prompt":"A learner can request more than one course. A course can have many learners. How should the ERD store those requests?","options":[{"id":"a","label":"A many-to-many line only, with status and requestedOn written beside the line"},{"id":"b","label":"courseId and status stored on Learner, so each learner can request only one course"},{"id":"c","label":"A Booking entity with learnerId, courseId, status and requestedOn"},{"id":"d","label":"One learnerId field on Course, so each course can have only one learner"}],"correctOptionId":"c","feedback":{"correct":"Booking is the linking entity. It stores one request: who, which course, the status and the date.","incorrect":"A line with notes cannot hold a row per request. Putting a single courseId on Learner, or a single learnerId on Course, blocks the many side."}}}]},{"schema":"lp.content.activity","schemaVersion":"0.1.0","id":"week-7-lesson-1-ex-13","version":"0.1.0","metadata":{"title":"Name the cardinality","status":"available","summary":"Match each Oakfield rule to the relationship type.","href":null,"difficulty":"standard","familyId":"week-7-lesson-1-ex-13","estimatedDurationMinutes":4,"activityType":"Matching","topics":["Cardinality"],"detail":"Match each Oakfield rule to the relationship type."},"relationships":{"learningOutcomes":["lo1","w7-process-erd","w7-interface-algo","w7-data"],"assignment":"os-formative","questions":[],"assets":[],"prerequisites":[]},"blocks":[{"schema":"lp.content.block","schemaVersion":"0.1.0","id":"week-7-lesson-1-ex-13-card","version":"0.1.0","metadata":{},"relationships":{},"type":"drag-drop","content":{"formative":true,"questionId":"week-7-lesson-1-ex-13:card","sourceQuestionId":"card","prompt":"Match each rule to the relationship type.","items":[{"id":"cs","label":"One course has many sessions. Each session is for one course."},{"id":"code","label":"Each booking has one confirmation code, and that code belongs to only that booking."},{"id":"ba","label":"Learners attend many sessions, and a session has many learners. Attendance stores each pair."}],"targets":[{"id":"m-om","label":"One-to-many"},{"id":"m-oo","label":"One-to-one"},{"id":"m-mm","label":"Many-to-many, stored with a linking entity"}],"correct":{"cs":"m-om","code":"m-oo","ba":"m-mm"},"feedback":{"correct":"Course to Session is one-to-many. A confirmation code is one-to-one with its booking, so it stays on Booking. Attendance resolves learner and session.","incorrect":"Do not treat Attendance as one-to-one. One session has many attendance rows."}}}]},{"schema":"lp.content.activity","schemaVersion":"0.1.0","id":"week-7-lesson-1-ex-14","version":"0.1.0","metadata":{"title":"Incorrect relationships","status":"available","summary":"Reject links that contradict the Oakfield rules.","href":null,"difficulty":"standard","familyId":"week-7-lesson-1-ex-14","estimatedDurationMinutes":5,"activityType":"Classification","topics":["ERD checks"],"detail":"Reject links that contradict the Oakfield rules."},"relationships":{"learningOutcomes":["lo1","w7-process-erd","w7-interface-algo","w7-data"],"assignment":"os-formative","questions":[],"assets":[],"prerequisites":[]},"blocks":[{"schema":"lp.content.block","schemaVersion":"0.1.0","id":"week-7-lesson-1-ex-14-wrong","version":"0.1.0","metadata":{},"relationships":{},"type":"classification","content":{"formative":true,"questionId":"week-7-lesson-1-ex-14:wrong","sourceQuestionId":"wrong","prompt":"Is each relationship statement acceptable for this design?","categories":[{"id":"ok","label":"Acceptable"},{"id":"bad","label":"Incorrect"}],"items":[{"id":"item-1","label":"Each session belongs to one course","correctCategoryId":"ok"},{"id":"item-2","label":"One session belongs to many courses at the same time","correctCategoryId":"bad"},{"id":"item-3","label":"A booking refers to one learner and one course","correctCategoryId":"ok"},{"id":"item-4","label":"An attendance row can be stored with no session","correctCategoryId":"bad"},{"id":"item-5","label":"learnerId on Booking stores a Course primary key","correctCategoryId":"bad"}],"feedback":{"correct":"Session belongs to one course. Booking points at one learner and one course. Attendance needs a session. A learner foreign key must point at Learner.","incorrect":"A foreign key must reference the entity it claims to link."}}}]},{"schema":"lp.content.activity","schemaVersion":"0.1.0","id":"week-7-lesson-1-ex-15","version":"0.1.0","metadata":{"title":"Duplicated data","status":"available","summary":"The same fact stored twice can get out of date.","href":null,"difficulty":"standard","familyId":"week-7-lesson-1-ex-15","estimatedDurationMinutes":3,"activityType":"Single choice","topics":["Data quality"],"detail":"The same fact stored twice can get out of date."},"relationships":{"learningOutcomes":["lo1","w7-process-erd","w7-interface-algo","w7-data"],"assignment":"os-formative","questions":[],"assets":[],"prerequisites":[]},"blocks":[{"schema":"lp.content.block","schemaVersion":"0.1.0","id":"week-7-lesson-1-ex-15-dup","version":"0.1.0","metadata":{},"relationships":{},"type":"single-choice","content":{"formative":true,"questionId":"week-7-lesson-1-ex-15:dup","sourceQuestionId":"dup","sourceType":"single","prompt":"Reception copies the learner name, phone and course title into a paper diary and again into a spreadsheet. What is the main data problem?","options":[{"id":"a","label":"The diary is a primary key and the spreadsheet is a foreign key"},{"id":"b","label":"The same facts are stored twice, so the copies can disagree"},{"id":"c","label":"Course title should be the primary key of Learner"},{"id":"d","label":"The spreadsheet is already an ERD, so no further data design is needed"}],"correctOptionId":"b","feedback":{"correct":"Two copies of the same facts drift apart. Store each fact once and link rows with keys.","incorrect":"A surname or a course title can repeat. Neither is a primary key, and a spreadsheet is not an ERD."}}}]},{"schema":"lp.content.activity","schemaVersion":"0.1.0","id":"week-7-lesson-1-ex-16","version":"0.1.0","metadata":{"title":"Plan the ERD before drawing","status":"available","summary":"List entities, keys and relationships in words. You will draw the diagram in the last activity.","href":null,"difficulty":"standard","familyId":"week-7-lesson-1-ex-16","estimatedDurationMinutes":8,"activityType":"Written response","topics":["ERD planning"],"detail":"List entities, keys and relationships in words. You will draw the diagram in the last activity."},"relationships":{"learningOutcomes":["lo1","w7-process-erd","w7-interface-algo","w7-data"],"assignment":"os-formative","questions":[],"assets":[],"prerequisites":[]},"blocks":[{"schema":"lp.content.block","schemaVersion":"0.1.0","id":"week-7-lesson-1-ex-16-brief","version":"0.1.0","metadata":{},"relationships":{},"type":"paragraph","content":{"text":"Use Learner, Course, Session, Booking and Attendance. A booking is one learner requesting one course. Attendance is one learner at one session."}},{"schema":"lp.content.block","schemaVersion":"0.1.0","id":"week-7-lesson-1-ex-16-plan","version":"0.1.0","metadata":{},"relationships":{},"type":"short-response","content":{"formative":true,"questionId":"week-7-lesson-1-ex-16:plan","sourceQuestionId":"plan","prompt":"List the five entities, the primary key of each, and three relationships in plain English. Note one foreign key.","placeholder":"Entities and primary keys:\n1. ...\n2. ...\n3. ...\n4. ...\n5. ...\nRelationships:\n1. ...\n2. ...\n3. ...\nForeign key: ...","guidance":"Include bookingId and courseId. Say which entity the foreign key sits on and which entity it points to.","minChars":80}}]},{"schema":"lp.content.activity","schemaVersion":"0.1.0","id":"week-7-lesson-1-ex-17","version":"0.1.0","metadata":{"title":"Check the ERD against the need","status":"available","summary":"A design that cannot answer the requirement is not finished.","href":null,"difficulty":"standard","familyId":"week-7-lesson-1-ex-17","estimatedDurationMinutes":4,"activityType":"Single choice","topics":["ERD checks"],"detail":"A design that cannot answer the requirement is not finished."},"relationships":{"learningOutcomes":["lo1","w7-process-erd","w7-interface-algo","w7-data"],"assignment":"os-formative","questions":[],"assets":[],"prerequisites":[]},"blocks":[{"schema":"lp.content.block","schemaVersion":"0.1.0","id":"week-7-lesson-1-ex-17-need","version":"0.1.0","metadata":{},"relationships":{},"type":"paragraph","content":{"text":"Tutors must see who requested a course, and who attended a particular session."}},{"schema":"lp.content.block","schemaVersion":"0.1.0","id":"week-7-lesson-1-ex-17-gap","version":"0.1.0","metadata":{},"relationships":{},"type":"single-choice","content":{"formative":true,"questionId":"week-7-lesson-1-ex-17:gap","sourceQuestionId":"gap","sourceType":"single","prompt":"The ERD has Learner, Course and Booking, but no Session or Attendance. Which requirement still fails?","options":[{"id":"a","label":"Who requested a place on a course"},{"id":"b","label":"The title of a course"},{"id":"c","label":"Who attended a particular session"},{"id":"d","label":"The learner's email address"}],"correctOptionId":"c","feedback":{"correct":"Booking can show who requested a course. Attendance of one session needs Session and Attendance.","incorrect":"Course title and email are already on Course and Learner. Do not add them again to fill this gap."}}}]},{"schema":"lp.content.activity","schemaVersion":"0.1.0","id":"week-7-lesson-1-ex-18","version":"0.1.0","metadata":{"title":"Draw the flowchart and the ERD","status":"available","summary":"Produce both diagrams outside the hub, then record the decisions here.","href":null,"difficulty":"standard","familyId":"week-7-lesson-1-ex-18","estimatedDurationMinutes":15,"activityType":"Written response","topics":["Process diagrams","ERD"],"detail":"Produce both diagrams outside the hub, then record the decisions here."},"relationships":{"learningOutcomes":["lo1","w7-process-erd","w7-interface-algo","w7-data"],"assignment":"os-formative","questions":[],"assets":[],"prerequisites":[]},"blocks":[{"schema":"lp.content.block","schemaVersion":"0.1.0","id":"week-7-lesson-1-ex-18-draw","version":"0.1.0","metadata":{},"relationships":{},"type":"paragraph","content":{"text":"Create two diagrams in diagrams.net (https://app.diagrams.net/), or on paper if you cannot open it. (1) A flowchart for request-a-place, with both the places-left path and the course-full path. (2) An ERD for Learner, Course, Session, Booking and Attendance, with primary keys, foreign keys and relationship names. Save the files with clear names, for example oakfield-request-flowchart and oakfield-erd. Submit those files separately, as your tutor instructs. This activity only records your decisions. Finishing it does not mean the diagrams have been assessed."}},{"schema":"lp.content.block","schemaVersion":"0.1.0","id":"week-7-lesson-1-ex-18-record","version":"0.1.0","metadata":{},"relationships":{},"type":"short-response","content":{"formative":true,"questionId":"week-7-lesson-1-ex-18:record","sourceQuestionId":"record","prompt":"Give the file names (or say paper) and where you will submit them. List the entities and relationships. Explain the decision and both paths.","placeholder":"Files: ...\nSubmitted to: ...\nEntities: ...\nRelationships: ...\nDecision: ...\nPlaces left: ...\nCourse full: ...","guidance":"Course full must not store a confirmed booking. Say whether each relationship is one-to-one, one-to-many, or many-to-many through Booking or Attendance.","minChars":120}}]},{"schema":"lp.content.activity","schemaVersion":"0.1.0","id":"week-7-lesson-2-ex-01","version":"0.1.0","metadata":{"title":"What an interface design is for","status":"available","summary":"The sketch is for checking the task, not for final branding.","href":null,"difficulty":"standard","familyId":"week-7-lesson-2-ex-01","estimatedDurationMinutes":3,"activityType":"Single choice","topics":["Interface design"],"detail":"The sketch is for checking the task, not for final branding."},"relationships":{"learningOutcomes":["lo1","w7-process-erd","w7-interface-algo","w7-data"],"assignment":"os-formative","questions":[],"assets":[],"prerequisites":[]},"blocks":[{"schema":"lp.content.block","schemaVersion":"0.1.0","id":"week-7-lesson-2-ex-01-purpose","version":"0.1.0","metadata":{},"relationships":{},"type":"single-choice","content":{"formative":true,"questionId":"week-7-lesson-2-ex-01:purpose","sourceQuestionId":"purpose","sourceType":"single","prompt":"Why produce an interface design for Oakfield's booking request before writing code?","options":[{"id":"a","label":"So the ERD can be dropped once the buttons exist"},{"id":"b","label":"So labels, actions and messages can be checked against the process before they are built"},{"id":"c","label":"So the final colour palette is fixed before the task is understood"},{"id":"d","label":"So the algorithm can be skipped, because the screen is the process"}],"correctOptionId":"b","feedback":{"correct":"The design shows how the request is completed. Check it against the process. The ERD and the algorithm still stand.","incorrect":"Colours can wait. A screen does not replace the steps or the stored data."}}}]},{"schema":"lp.content.activity","schemaVersion":"0.1.0","id":"week-7-lesson-2-ex-02","version":"0.1.0","metadata":{"title":"Follow the user journey","status":"available","summary":"The screens should follow the process, not invent a new one.","href":null,"difficulty":"standard","familyId":"week-7-lesson-2-ex-02","estimatedDurationMinutes":3,"activityType":"Single choice","topics":["User journeys"],"detail":"The screens should follow the process, not invent a new one."},"relationships":{"learningOutcomes":["lo1","w7-process-erd","w7-interface-algo","w7-data"],"assignment":"os-formative","questions":[],"assets":[],"prerequisites":[]},"blocks":[{"schema":"lp.content.block","schemaVersion":"0.1.0","id":"week-7-lesson-2-ex-02-journey","version":"0.1.0","metadata":{},"relationships":{},"type":"single-choice","content":{"formative":true,"questionId":"week-7-lesson-2-ex-02:journey","sourceQuestionId":"journey","sourceType":"single","prompt":"A learner is requesting a place. Which journey matches the process from Lesson 1?","options":[{"id":"a","label":"Choose a published course, submit the request, then see confirmation or a course-full message"},{"id":"b","label":"See the course-full message first, then choose the course it referred to"},{"id":"c","label":"Store the confirmed booking, then ask for the email the confirmation needed"},{"id":"d","label":"Open a session register, then create the booking that register depends on"}],"correctOptionId":"a","feedback":{"correct":"The journey is choose, request, then one result. A full course does not create a booking.","incorrect":"Do not confirm a booking before the course and the email are known, and do not start from the register."}}}]},{"schema":"lp.content.activity","schemaVersion":"0.1.0","id":"week-7-lesson-2-ex-03","version":"0.1.0","metadata":{"title":"Interface requirements","status":"available","summary":"Separate what the screen must do from decoration.","href":null,"difficulty":"standard","familyId":"week-7-lesson-2-ex-03","estimatedDurationMinutes":4,"activityType":"Classification","topics":["Requirements"],"detail":"Separate what the screen must do from decoration."},"relationships":{"learningOutcomes":["lo1","w7-process-erd","w7-interface-algo","w7-data"],"assignment":"os-formative","questions":[],"assets":[],"prerequisites":[]},"blocks":[{"schema":"lp.content.block","schemaVersion":"0.1.0","id":"week-7-lesson-2-ex-03-reqs","version":"0.1.0","metadata":{},"relationships":{},"type":"classification","content":{"formative":true,"questionId":"week-7-lesson-2-ex-03:reqs","sourceQuestionId":"reqs","prompt":"Classify each item for the first booking-request screen.","categories":[{"id":"must","label":"Needed for the task"},{"id":"later","label":"Can wait"},{"id":"no","label":"Does not belong"}],"items":[{"id":"item-1","label":"A way to choose the course","correctCategoryId":"must"},{"id":"item-2","label":"Labels that say what to type","correctCategoryId":"must"},{"id":"item-3","label":"A final illustrated brand campaign","correctCategoryId":"later"},{"id":"item-4","label":"A control to submit the request","correctCategoryId":"must"},{"id":"item-5","label":"A button that deletes every course","correctCategoryId":"no"}],"feedback":{"correct":"The first screen must identify the course, label the fields and submit the request. A brand campaign can wait. Deleting courses is a different job.","incorrect":"Do not treat a destructive admin action as part of requesting a place."}}}]},{"schema":"lp.content.activity","schemaVersion":"0.1.0","id":"week-7-lesson-2-ex-04","version":"0.1.0","metadata":{"title":"What a wireframe is","status":"available","summary":"Low fidelity is enough for this lesson.","href":null,"difficulty":"standard","familyId":"week-7-lesson-2-ex-04","estimatedDurationMinutes":3,"activityType":"Single choice","topics":["Wireframes"],"detail":"Low fidelity is enough for this lesson."},"relationships":{"learningOutcomes":["lo1","w7-process-erd","w7-interface-algo","w7-data"],"assignment":"os-formative","questions":[],"assets":[],"prerequisites":[]},"blocks":[{"schema":"lp.content.block","schemaVersion":"0.1.0","id":"week-7-lesson-2-ex-04-wire","version":"0.1.0","metadata":{},"relationships":{},"type":"single-choice","content":{"formative":true,"questionId":"week-7-lesson-2-ex-04:wire","sourceQuestionId":"wire","sourceType":"single","prompt":"Which description best fits a wireframe for this lesson?","options":[{"id":"a","label":"The finished screen, with final photos and animation"},{"id":"b","label":"A layout of regions, labels, the request action and the result message, without final branding"},{"id":"c","label":"The ERD, drawn as boxes because a wireframe should show the tables"},{"id":"d","label":"A colour palette, with no labels and no actions"}],"correctOptionId":"b","feedback":{"correct":"A wireframe is a layout you can discuss. Labels, the action and the result matter more than polish.","incorrect":"An ERD is not a wireframe. A palette with no labels cannot be checked against the process."}}}]},{"schema":"lp.content.activity","schemaVersion":"0.1.0","id":"week-7-lesson-2-ex-05","version":"0.1.0","metadata":{"title":"Layout that can be used","status":"available","summary":"Group the request fields so the task is obvious.","href":null,"difficulty":"standard","familyId":"week-7-lesson-2-ex-05","estimatedDurationMinutes":4,"activityType":"Classification","topics":["Layout"],"detail":"Group the request fields so the task is obvious."},"relationships":{"learningOutcomes":["lo1","w7-process-erd","w7-interface-algo","w7-data"],"assignment":"os-formative","questions":[],"assets":[],"prerequisites":[]},"blocks":[{"schema":"lp.content.block","schemaVersion":"0.1.0","id":"week-7-lesson-2-ex-05-layout","version":"0.1.0","metadata":{},"relationships":{},"type":"classification","content":{"formative":true,"questionId":"week-7-lesson-2-ex-05:layout","sourceQuestionId":"layout","prompt":"For a booking-request screen, classify each layout choice.","categories":[{"id":"good","label":"Helps the task"},{"id":"poor","label":"Gets in the way"}],"items":[{"id":"item-1","label":"Course choice, learner details and the submit button are grouped in that order","correctCategoryId":"good"},{"id":"item-2","label":"The submit button is placed before any field, with the course choice in a footnote","correctCategoryId":"poor"},{"id":"item-3","label":"The confirmation message has its own clear area","correctCategoryId":"good"},{"id":"item-4","label":"Essential fields are scattered in four corners with no headings","correctCategoryId":"poor"}],"feedback":{"correct":"Order the screen the way the task is done. Keep the result message easy to find.","incorrect":"A submit button before the fields invites an empty request."}}}]},{"schema":"lp.content.activity","schemaVersion":"0.1.0","id":"week-7-lesson-2-ex-06","version":"0.1.0","metadata":{"title":"Navigation","status":"available","summary":"People need a clear way in and a clear way back.","href":null,"difficulty":"standard","familyId":"week-7-lesson-2-ex-06","estimatedDurationMinutes":3,"activityType":"Single choice","topics":["Navigation"],"detail":"People need a clear way in and a clear way back."},"relationships":{"learningOutcomes":["lo1","w7-process-erd","w7-interface-algo","w7-data"],"assignment":"os-formative","questions":[],"assets":[],"prerequisites":[]},"blocks":[{"schema":"lp.content.block","schemaVersion":"0.1.0","id":"week-7-lesson-2-ex-06-nav","version":"0.1.0","metadata":{},"relationships":{},"type":"single-choice","content":{"formative":true,"questionId":"week-7-lesson-2-ex-06:nav","sourceQuestionId":"nav","sourceType":"single","prompt":"A learner has opened the wrong course. Which navigation choice is most suitable?","options":[{"id":"a","label":"No way back. The learner must close the browser and start again"},{"id":"b","label":"One link labelled Click here, which opens either the register or the home page"},{"id":"c","label":"The tutor menu for reports and course editing, placed on the learner's form"},{"id":"d","label":"A clear return to the published course list, still inside the request journey"}],"correctOptionId":"d","feedback":{"correct":"The learner needs a way back to the course list without leaving the task.","incorrect":"A shared label that changes destination, or the tutor's menu, does not support this journey."}}}]},{"schema":"lp.content.activity","schemaVersion":"0.1.0","id":"week-7-lesson-2-ex-07","version":"0.1.0","metadata":{"title":"Visual hierarchy","status":"available","summary":"The main action should be the easiest thing to find.","href":null,"difficulty":"standard","familyId":"week-7-lesson-2-ex-07","estimatedDurationMinutes":3,"activityType":"Single choice","topics":["Visual hierarchy"],"detail":"The main action should be the easiest thing to find."},"relationships":{"learningOutcomes":["lo1","w7-process-erd","w7-interface-algo","w7-data"],"assignment":"os-formative","questions":[],"assets":[],"prerequisites":[]},"blocks":[{"schema":"lp.content.block","schemaVersion":"0.1.0","id":"week-7-lesson-2-ex-07-hier","version":"0.1.0","metadata":{},"relationships":{},"type":"single-choice","content":{"formative":true,"questionId":"week-7-lesson-2-ex-07:hier","sourceQuestionId":"hier","sourceType":"single","prompt":"On the booking-request screen, which item should stand out as the primary action?","options":[{"id":"a","label":"A link called More, the same size as the privacy footer"},{"id":"b","label":"Request place, easier to see than Cancel, and named as the action"},{"id":"c","label":"Delete all courses, the same size and weight as Request place"},{"id":"d","label":"Three buttons that all repeat the page title"}],"correctOptionId":"b","feedback":{"correct":"The main action should be recognisable and should say what it does.","incorrect":"Delete all courses is not the request action. Equal buttons with no verb force the learner to guess."}}}]},{"schema":"lp.content.activity","schemaVersion":"0.1.0","id":"week-7-lesson-2-ex-08","version":"0.1.0","metadata":{"title":"Consistency","status":"available","summary":"Use the same words for the same things.","href":null,"difficulty":"standard","familyId":"week-7-lesson-2-ex-08","estimatedDurationMinutes":4,"activityType":"Classification","topics":["Consistency"],"detail":"Use the same words for the same things."},"relationships":{"learningOutcomes":["lo1","w7-process-erd","w7-interface-algo","w7-data"],"assignment":"os-formative","questions":[],"assets":[],"prerequisites":[]},"blocks":[{"schema":"lp.content.block","schemaVersion":"0.1.0","id":"week-7-lesson-2-ex-08-consist","version":"0.1.0","metadata":{},"relationships":{},"type":"classification","content":{"formative":true,"questionId":"week-7-lesson-2-ex-08:consist","sourceQuestionId":"consist","prompt":"Classify each pair of labels.","categories":[{"id":"ok","label":"Consistent"},{"id":"mix","label":"Inconsistent"}],"items":[{"id":"item-1","label":"The button says Request place and the confirmation says Place requested","correctCategoryId":"ok"},{"id":"item-2","label":"One screen says Course and the next calls the same thing Product SKU","correctCategoryId":"mix"},{"id":"item-3","label":"Both the form and the error use the words email address","correctCategoryId":"ok"},{"id":"item-4","label":"Submit, Go, OK and Send are used at random for the same request action","correctCategoryId":"mix"}],"feedback":{"correct":"Use one name for the course and one name for the action. Confirmation wording can complete that action.","incorrect":"Product SKU is a different language from the Oakfield brief."}}}]},{"schema":"lp.content.activity","schemaVersion":"0.1.0","id":"week-7-lesson-2-ex-09","version":"0.1.0","metadata":{"title":"Accessibility in the sketch","status":"available","summary":"Access needs are part of the design, not a later coat of paint.","href":null,"difficulty":"standard","familyId":"week-7-lesson-2-ex-09","estimatedDurationMinutes":4,"activityType":"Single choice","topics":["Accessibility"],"detail":"Access needs are part of the design, not a later coat of paint."},"relationships":{"learningOutcomes":["lo1","w7-process-erd","w7-interface-algo","w7-data"],"assignment":"os-formative","questions":[],"assets":[],"prerequisites":[]},"blocks":[{"schema":"lp.content.block","schemaVersion":"0.1.0","id":"week-7-lesson-2-ex-09-a11y","version":"0.1.0","metadata":{},"relationships":{},"type":"single-choice","content":{"formative":true,"questionId":"week-7-lesson-2-ex-09:a11y","sourceQuestionId":"a11y","sourceType":"single","prompt":"Which design choice best supports learners who use a keyboard or a screen reader?","options":[{"id":"a","label":"Instructions given only by a red outline, with no text"},{"id":"b","label":"Placeholder text used instead of a label, so the hint disappears when typing starts"},{"id":"c","label":"Icon-only buttons, with no text alternative"},{"id":"d","label":"A visible text label on every input, and a result that is not conveyed by colour alone"}],"correctOptionId":"d","feedback":{"correct":"Text labels and a text result still work with a keyboard, a screen reader or magnification.","incorrect":"Colour, a vanishing placeholder or an icon with no text leaves the instruction unavailable to some learners."}}}]},{"schema":"lp.content.activity","schemaVersion":"0.1.0","id":"week-7-lesson-2-ex-10","version":"0.1.0","metadata":{"title":"Usability problems","status":"available","summary":"Name problems a learner would hit, not visual taste.","href":null,"difficulty":"standard","familyId":"week-7-lesson-2-ex-10","estimatedDurationMinutes":4,"activityType":"Classification","topics":["Usability"],"detail":"Name problems a learner would hit, not visual taste."},"relationships":{"learningOutcomes":["lo1","w7-process-erd","w7-interface-algo","w7-data"],"assignment":"os-formative","questions":[],"assets":[],"prerequisites":[]},"blocks":[{"schema":"lp.content.block","schemaVersion":"0.1.0","id":"week-7-lesson-2-ex-10-use","version":"0.1.0","metadata":{},"relationships":{},"type":"classification","content":{"formative":true,"questionId":"week-7-lesson-2-ex-10:use","sourceQuestionId":"use","prompt":"Classify each issue on a draft booking screen.","categories":[{"id":"block","label":"Blocks the task"},{"id":"minor","label":"Minor, can wait"}],"items":[{"id":"item-1","label":"The course-full message never appears, so the learner thinks the request succeeded","correctCategoryId":"block"},{"id":"item-2","label":"The footer copyright year is 2024 rather than 2026","correctCategoryId":"minor"},{"id":"item-3","label":"Required fields are not marked, and an empty form can be submitted","correctCategoryId":"block"},{"id":"item-4","label":"The page heading is 2 pixels smaller than the style guide","correctCategoryId":"minor"}],"feedback":{"correct":"A missing result and an empty submit stop the real task. A slightly small heading does not.","incorrect":"Do not treat a wrong copyright year as more serious than a false confirmation."}}}]},{"schema":"lp.content.activity","schemaVersion":"0.1.0","id":"week-7-lesson-2-ex-11","version":"0.1.0","metadata":{"title":"Inputs and outputs","status":"available","summary":"The screen both collects data and shows a result.","href":null,"difficulty":"standard","familyId":"week-7-lesson-2-ex-11","estimatedDurationMinutes":4,"activityType":"Classification","topics":["Inputs and outputs"],"detail":"The screen both collects data and shows a result."},"relationships":{"learningOutcomes":["lo1","w7-process-erd","w7-interface-algo","w7-data"],"assignment":"os-formative","questions":[],"assets":[],"prerequisites":[]},"blocks":[{"schema":"lp.content.block","schemaVersion":"0.1.0","id":"week-7-lesson-2-ex-11-io","version":"0.1.0","metadata":{},"relationships":{},"type":"classification","content":{"formative":true,"questionId":"week-7-lesson-2-ex-11:io","sourceQuestionId":"io","prompt":"Classify each item on the booking journey.","categories":[{"id":"in","label":"Input"},{"id":"out","label":"Output"}],"items":[{"id":"item-1","label":"The course the learner chooses","correctCategoryId":"in"},{"id":"item-2","label":"The email address the learner types","correctCategoryId":"in"},{"id":"item-3","label":"The message that the place is confirmed","correctCategoryId":"out"},{"id":"item-4","label":"The message that the course is full","correctCategoryId":"out"}],"feedback":{"correct":"The course and email go into the process. The confirmation and full messages come out.","incorrect":"A message the learner reads is an output."}}}]},{"schema":"lp.content.activity","schemaVersion":"0.1.0","id":"week-7-lesson-2-ex-12","version":"0.1.0","metadata":{"title":"What an algorithm is here","status":"available","summary":"An algorithm is the ordered steps that carry out the task.","href":null,"difficulty":"standard","familyId":"week-7-lesson-2-ex-12","estimatedDurationMinutes":3,"activityType":"Single choice","topics":["Algorithms"],"detail":"An algorithm is the ordered steps that carry out the task."},"relationships":{"learningOutcomes":["lo1","w7-process-erd","w7-interface-algo","w7-data"],"assignment":"os-formative","questions":[],"assets":[],"prerequisites":[]},"blocks":[{"schema":"lp.content.block","schemaVersion":"0.1.0","id":"week-7-lesson-2-ex-12-algo","version":"0.1.0","metadata":{},"relationships":{},"type":"single-choice","content":{"formative":true,"questionId":"week-7-lesson-2-ex-12:algo","sourceQuestionId":"algo","sourceType":"single","prompt":"Which statement best describes the algorithm for requesting a place?","options":[{"id":"a","label":"The colours chosen for the confirmation message"},{"id":"b","label":"The ERD, because the algorithm is the list of entities"},{"id":"c","label":"The ordered checks, then the choice between a confirmed booking and a course-full message"},{"id":"d","label":"The wireframe boxes, with no decisions written down"}],"correctOptionId":"c","feedback":{"correct":"The algorithm is the order of checks and the two results. It should match the buttons on the wireframe.","incorrect":"Colours, entities and boxes are parts of other design products. They are not the steps."}}}]},{"schema":"lp.content.activity","schemaVersion":"0.1.0","id":"week-7-lesson-2-ex-13","version":"0.1.0","metadata":{"title":"Sequence the steps","status":"available","summary":"Order matters. Validation comes before storing a booking.","href":null,"difficulty":"standard","familyId":"week-7-lesson-2-ex-13","estimatedDurationMinutes":3,"activityType":"Single choice","topics":["Sequencing"],"detail":"Order matters. Validation comes before storing a booking."},"relationships":{"learningOutcomes":["lo1","w7-process-erd","w7-interface-algo","w7-data"],"assignment":"os-formative","questions":[],"assets":[],"prerequisites":[]},"blocks":[{"schema":"lp.content.block","schemaVersion":"0.1.0","id":"week-7-lesson-2-ex-13-seq","version":"0.1.0","metadata":{},"relationships":{},"type":"single-choice","content":{"formative":true,"questionId":"week-7-lesson-2-ex-13:seq","sourceQuestionId":"seq","sourceType":"single","prompt":"Which sequence is safe?","options":[{"id":"a","label":"Store Confirmed, then check that a course was chosen, then check places left"},{"id":"b","label":"Read the course and email, reject blanks, check places left, then store Confirmed or show course full"},{"id":"c","label":"Show course full for every request, then ask which course was meant"},{"id":"d","label":"Write an attendance row, then create the booking that row refers to"}],"correctOptionId":"b","feedback":{"correct":"Check the inputs and the places before storing a confirmed booking. A full course is a message, not a stored booking.","incorrect":"Storing Confirmed first, or writing attendance before the booking, records a result you have not checked."}}}]},{"schema":"lp.content.activity","schemaVersion":"0.1.0","id":"week-7-lesson-2-ex-14","version":"0.1.0","metadata":{"title":"Selection with IF","status":"available","summary":"Predict the result. Do not assume the condition is the right way round.","href":null,"difficulty":"standard","familyId":"week-7-lesson-2-ex-14","estimatedDurationMinutes":4,"activityType":"Single choice","topics":["Selection"],"detail":"Predict the result. Do not assume the condition is the right way round."},"relationships":{"learningOutcomes":["lo1","w7-process-erd","w7-interface-algo","w7-data"],"assignment":"os-formative","questions":[],"assets":[],"prerequisites":[]},"blocks":[{"schema":"lp.content.block","schemaVersion":"0.1.0","id":"week-7-lesson-2-ex-14-code","version":"0.1.0","metadata":{},"relationships":{},"type":"paragraph","content":{"text":"placesLeft = 0. IF placesLeft > 0 THEN result = Confirmed ELSE result = Course full."}},{"schema":"lp.content.block","schemaVersion":"0.1.0","id":"week-7-lesson-2-ex-14-if","version":"0.1.0","metadata":{},"relationships":{},"type":"single-choice","content":{"formative":true,"questionId":"week-7-lesson-2-ex-14:if","sourceQuestionId":"if","sourceType":"single","prompt":"What is result after this selection?","options":[{"id":"a","label":"Confirmed"},{"id":"b","label":"Course full"},{"id":"c","label":"Confirmed and Course full"},{"id":"d","label":"Blank, because the decision is skipped when placesLeft is 0"}],"correctOptionId":"b","feedback":{"correct":"The condition is false, so the ELSE path runs and result is Course full. That is a message, not a stored booking.","incorrect":"Read the condition. Zero places must not take the Confirmed path, and the IF still runs."}}}]},{"schema":"lp.content.activity","schemaVersion":"0.1.0","id":"week-7-lesson-2-ex-15","version":"0.1.0","metadata":{"title":"Why a loop is used","status":"available","summary":"A loop repeats a step when there are many similar items.","href":null,"difficulty":"standard","familyId":"week-7-lesson-2-ex-15","estimatedDurationMinutes":4,"activityType":"Single choice","topics":["Iteration"],"detail":"A loop repeats a step when there are many similar items."},"relationships":{"learningOutcomes":["lo1","w7-process-erd","w7-interface-algo","w7-data"],"assignment":"os-formative","questions":[],"assets":[],"prerequisites":[]},"blocks":[{"schema":"lp.content.block","schemaVersion":"0.1.0","id":"week-7-lesson-2-ex-15-loop","version":"0.1.0","metadata":{},"relationships":{},"type":"single-choice","content":{"formative":true,"questionId":"week-7-lesson-2-ex-15:loop","sourceQuestionId":"loop","sourceType":"single","prompt":"A course has several sessions. The register should open only for the session whose date is today. Why is a loop suitable?","options":[{"id":"a","label":"Check each session in turn, and stop when sessionDate is today"},{"id":"b","label":"Delete every session whose date is not today"},{"id":"c","label":"A loop cannot contain an IF, so the date check is avoided"},{"id":"d","label":"The course has only one session, so a loop is the way to select it"}],"correctOptionId":"a","feedback":{"correct":"There may be many sessions. The loop examines each one and stops when today's date matches.","incorrect":"Do not delete other sessions. A single session would not need this loop, and a loop can contain a decision."}}}]},{"schema":"lp.content.activity","schemaVersion":"0.1.0","id":"week-7-lesson-2-ex-16","version":"0.1.0","metadata":{"title":"Faults in pseudocode","status":"available","summary":"Find the logical mistake, not a spelling preference.","href":null,"difficulty":"standard","familyId":"week-7-lesson-2-ex-16","estimatedDurationMinutes":5,"activityType":"Classification","topics":["Pseudocode"],"detail":"Find the logical mistake, not a spelling preference."},"relationships":{"learningOutcomes":["lo1","w7-process-erd","w7-interface-algo","w7-data"],"assignment":"os-formative","questions":[],"assets":[],"prerequisites":[]},"blocks":[{"schema":"lp.content.block","schemaVersion":"0.1.0","id":"week-7-lesson-2-ex-16-faults","version":"0.1.0","metadata":{},"relationships":{},"type":"classification","content":{"formative":true,"questionId":"week-7-lesson-2-ex-16:faults","sourceQuestionId":"faults","prompt":"Classify each piece of pseudocode for 'confirm only when places remain'.","categories":[{"id":"ok","label":"Does the right thing"},{"id":"bad","label":"Logical mistake"}],"items":[{"id":"item-1","label":"IF placesLeft > 0 THEN result = Confirmed ELSE result = Course full","correctCategoryId":"ok"},{"id":"item-2","label":"IF placesLeft = 0 THEN result = Confirmed ELSE result = Course full","correctCategoryId":"bad"},{"id":"item-3","label":"IF email is blank THEN show Enter an email address and do not store a booking","correctCategoryId":"ok"},{"id":"item-4","label":"Set result = Confirmed, then check placesLeft","correctCategoryId":"bad"}],"feedback":{"correct":"Confirm only when places remain, and check the email before storing. Item 2 confirms an empty course. Item 4 chooses Confirmed before the check.","incorrect":"Read which branch runs when placesLeft is 0. Course full is a message, not a Booking row."}}}]},{"schema":"lp.content.activity","schemaVersion":"0.1.0","id":"week-7-lesson-2-ex-17","version":"0.1.0","metadata":{"title":"Tie a step to a control","status":"available","summary":"Every important screen action needs a step, and every result needs a place on the screen.","href":null,"difficulty":"standard","familyId":"week-7-lesson-2-ex-17","estimatedDurationMinutes":6,"activityType":"Written response","topics":["Interface","Algorithms"],"detail":"Every important screen action needs a step, and every result needs a place on the screen."},"relationships":{"learningOutcomes":["lo1","w7-process-erd","w7-interface-algo","w7-data"],"assignment":"os-formative","questions":[],"assets":[],"prerequisites":[]},"blocks":[{"schema":"lp.content.block","schemaVersion":"0.1.0","id":"week-7-lesson-2-ex-17-link","version":"0.1.0","metadata":{},"relationships":{},"type":"short-response","content":{"formative":true,"questionId":"week-7-lesson-2-ex-17:link","sourceQuestionId":"link","prompt":"For the Request place button, write the checks the algorithm should run and the message each outcome shows on screen.","placeholder":"When Request place is used:\nChecks: ...\nIf places remain: screen shows ... Booking stored: ...\nIf the course is full: screen shows ... Booking stored: none\nIf email is missing: screen shows ...","guidance":"Name the button, the checks, and both capacity outcomes. Say whether a confirmed booking is stored.","minChars":80}}]},{"schema":"lp.content.activity","schemaVersion":"0.1.0","id":"week-7-lesson-2-ex-18","version":"0.1.0","metadata":{"title":"Two wireframes and the pseudocode","status":"available","summary":"Prepare the designs another developer could follow. Draw them outside the hub.","href":null,"difficulty":"standard","familyId":"week-7-lesson-2-ex-18","estimatedDurationMinutes":15,"activityType":"Written response","topics":["Wireframes","Pseudocode"],"detail":"Prepare the designs another developer could follow. Draw them outside the hub."},"relationships":{"learningOutcomes":["lo1","w7-process-erd","w7-interface-algo","w7-data"],"assignment":"os-formative","questions":[],"assets":[],"prerequisites":[]},"blocks":[{"schema":"lp.content.block","schemaVersion":"0.1.0","id":"week-7-lesson-2-ex-18-draw","version":"0.1.0","metadata":{},"relationships":{},"type":"paragraph","content":{"text":"In diagrams.net (https://app.diagrams.net/), or on paper, draw two annotated wireframes: the request screen, and the result screen (confirmed or course full). Annotate the labels, the primary action and one accessibility point. Write pseudocode for Request place, with a blank-email check and the places check. Save the files with clear names and submit them separately, as your tutor instructs. The boxes below record your decisions only. Completing them does not mean the wireframes have been assessed."}},{"schema":"lp.content.block","schemaVersion":"0.1.0","id":"week-7-lesson-2-ex-18-pack","version":"0.1.0","metadata":{},"relationships":{},"type":"short-response","content":{"formative":true,"questionId":"week-7-lesson-2-ex-18:pack","sourceQuestionId":"pack","prompt":"Give the file names and where you will submit them. Describe both screens, one accessibility point, and the pseudocode.","placeholder":"Files: ...\nSubmitted to: ...\nRequest screen: ...\nResult screen: ...\nAccessibility: ...\nPseudocode:\n1. ...","guidance":"Do not store Confirmed when placesLeft is 0 or the email is blank. Use IF/ELSE. Course full is a message, not a Booking row.","minChars":140}}]},{"schema":"lp.content.activity","schemaVersion":"0.1.0","id":"week-7-lesson-3-ex-01","version":"0.1.0","metadata":{"title":"What a data requirement is","status":"available","summary":"Say what must be stored, not how the screen is coloured.","href":null,"difficulty":"standard","familyId":"week-7-lesson-3-ex-01","estimatedDurationMinutes":3,"activityType":"Single choice","topics":["Data requirements"],"detail":"Say what must be stored, not how the screen is coloured."},"relationships":{"learningOutcomes":["lo1","w7-process-erd","w7-interface-algo","w7-data"],"assignment":"os-formative","questions":[],"assets":[],"prerequisites":[]},"blocks":[{"schema":"lp.content.block","schemaVersion":"0.1.0","id":"week-7-lesson-3-ex-01-what","version":"0.1.0","metadata":{},"relationships":{},"type":"single-choice","content":{"formative":true,"questionId":"week-7-lesson-3-ex-01:what","sourceQuestionId":"what","sourceType":"single","prompt":"Which statement is a data requirement for Oakfield?","options":[{"id":"a","label":"The submit button on the request screen must be blue"},{"id":"b","label":"The system must store which learner requested which course, and whether that booking was confirmed"},{"id":"c","label":"The wireframe must be drawn before the entity list is agreed"},{"id":"d","label":"The request screen must display the course title, which is read from Course"}],"correctOptionId":"b","feedback":{"correct":"A data requirement names a fact the system must keep. Who requested which course, and the booking status, have to be stored.","incorrect":"Button colour and draw order are not stored facts. Showing the title uses Course. It does not create a new fact."}}}]},{"schema":"lp.content.activity","schemaVersion":"0.1.0","id":"week-7-lesson-3-ex-02","version":"0.1.0","metadata":{"title":"What must be stored","status":"available","summary":"Separate stored facts from labels and from things Oakfield does not need.","href":null,"difficulty":"standard","familyId":"week-7-lesson-3-ex-02","estimatedDurationMinutes":4,"activityType":"Classification","topics":["Stored data"],"detail":"Separate stored facts from labels and from things Oakfield does not need."},"relationships":{"learningOutcomes":["lo1","w7-process-erd","w7-interface-algo","w7-data"],"assignment":"os-formative","questions":[],"assets":[],"prerequisites":[]},"blocks":[{"schema":"lp.content.block","schemaVersion":"0.1.0","id":"week-7-lesson-3-ex-02-store","version":"0.1.0","metadata":{},"relationships":{},"type":"classification","content":{"formative":true,"questionId":"week-7-lesson-3-ex-02:store","sourceQuestionId":"store","prompt":"Classify each item for the booking service.","categories":[{"id":"store","label":"Must be stored"},{"id":"show","label":"Shown from stored data, not a new fact"},{"id":"skip","label":"Not needed"}],"items":[{"id":"item-1","label":"Which learner made the request","correctCategoryId":"store"},{"id":"item-2","label":"Which course was requested","correctCategoryId":"store"},{"id":"item-3","label":"The course title printed on a confirmation, taken from Course","correctCategoryId":"show"},{"id":"item-4","label":"Whether the learner attended a session","correctCategoryId":"store"},{"id":"item-5","label":"Room name copied onto every Attendance row as well as stored on Session","correctCategoryId":"skip"}],"feedback":{"correct":"Store who requested the course and whether they attended. Read the course title from Course. Do not copy the room onto Attendance.","incorrect":"A duplicated room name can disagree with Session. Shoe size and similar extras are not required either."}}}]},{"schema":"lp.content.activity","schemaVersion":"0.1.0","id":"week-7-lesson-3-ex-03","version":"0.1.0","metadata":{"title":"Entity or attribute, again","status":"available","summary":"Use the same five entities. Put each field on the right one.","href":null,"difficulty":"standard","familyId":"week-7-lesson-3-ex-03","estimatedDurationMinutes":4,"activityType":"Classification","topics":["Entities","Attributes"],"detail":"Use the same five entities. Put each field on the right one."},"relationships":{"learningOutcomes":["lo1","w7-process-erd","w7-interface-algo","w7-data"],"assignment":"os-formative","questions":[],"assets":[],"prerequisites":[]},"blocks":[{"schema":"lp.content.block","schemaVersion":"0.1.0","id":"week-7-lesson-3-ex-03-place","version":"0.1.0","metadata":{},"relationships":{},"type":"classification","content":{"formative":true,"questionId":"week-7-lesson-3-ex-03:place","sourceQuestionId":"place","prompt":"Which entity owns each field?","categories":[{"id":"booking","label":"Booking"},{"id":"session","label":"Session"},{"id":"attend","label":"Attendance"},{"id":"course","label":"Course"}],"items":[{"id":"item-1","label":"requestedOn","correctCategoryId":"booking"},{"id":"item-2","label":"sessionDate","correctCategoryId":"session"},{"id":"item-3","label":"present, yes or no for that learner at that session","correctCategoryId":"attend"},{"id":"item-4","label":"maxPlaces","correctCategoryId":"course"},{"id":"item-5","label":"status of the place request","correctCategoryId":"booking"}],"feedback":{"correct":"Request date and status belong to the booking. The session has the date. Attendance stores whether that learner was present. Capacity belongs to the course.","incorrect":"Do not put maxPlaces on every attendance row."}}}]},{"schema":"lp.content.activity","schemaVersion":"0.1.0","id":"week-7-lesson-3-ex-04","version":"0.1.0","metadata":{"title":"Pick a suitable type","status":"available","summary":"The type should match the kind of value, not the longest word available.","href":null,"difficulty":"standard","familyId":"week-7-lesson-3-ex-04","estimatedDurationMinutes":3,"activityType":"Single choice","topics":["Data types"],"detail":"The type should match the kind of value, not the longest word available."},"relationships":{"learningOutcomes":["lo1","w7-process-erd","w7-interface-algo","w7-data"],"assignment":"os-formative","questions":[],"assets":[],"prerequisites":[]},"blocks":[{"schema":"lp.content.block","schemaVersion":"0.1.0","id":"week-7-lesson-3-ex-04-type","version":"0.1.0","metadata":{},"relationships":{},"type":"single-choice","content":{"formative":true,"questionId":"week-7-lesson-3-ex-04:type","sourceQuestionId":"type","sourceType":"single","prompt":"maxPlaces is the number of learners allowed on a course, such as 18. Which type is suitable?","options":[{"id":"a","label":"Text, for a sentence such as 'about 18 people'"},{"id":"b","label":"Whole number"},{"id":"c","label":"Boolean"},{"id":"d","label":"Date"}],"correctOptionId":"b","feedback":{"correct":"Capacity is a whole number, so it can be compared with places already booked.","incorrect":"A sentence cannot be compared safely. Boolean has only two values. A date is a calendar day, not a count."}}}]},{"schema":"lp.content.activity","schemaVersion":"0.1.0","id":"week-7-lesson-3-ex-05","version":"0.1.0","metadata":{"title":"Text or number","status":"available","summary":"Do not store quantities as uncontrolled text if you need to calculate.","href":null,"difficulty":"standard","familyId":"week-7-lesson-3-ex-05","estimatedDurationMinutes":4,"activityType":"Classification","topics":["Data types"],"detail":"Do not store quantities as uncontrolled text if you need to calculate."},"relationships":{"learningOutcomes":["lo1","w7-process-erd","w7-interface-algo","w7-data"],"assignment":"os-formative","questions":[],"assets":[],"prerequisites":[]},"blocks":[{"schema":"lp.content.block","schemaVersion":"0.1.0","id":"week-7-lesson-3-ex-05-tn","version":"0.1.0","metadata":{},"relationships":{},"type":"classification","content":{"formative":true,"questionId":"week-7-lesson-3-ex-05:tn","sourceQuestionId":"tn","prompt":"Choose a type.","categories":[{"id":"text","label":"Text"},{"id":"num","label":"Whole number"},{"id":"bad","label":"Unsuitable choice shown"}],"items":[{"id":"item-1","label":"Surname","correctCategoryId":"text"},{"id":"item-2","label":"maxPlaces","correctCategoryId":"num"},{"id":"item-3","label":"Storing maxPlaces as free text such as 'about eighteen people-ish'","correctCategoryId":"bad"},{"id":"item-4","label":"Email address","correctCategoryId":"text"},{"id":"item-5","label":"Storing surname as a whole number","correctCategoryId":"bad"}],"feedback":{"correct":"Names and emails are text. Capacity is a whole number. Vague sentences and numeric surnames break the design.","incorrect":"You cannot add up places if the value is a sentence."}}}]},{"schema":"lp.content.activity","schemaVersion":"0.1.0","id":"week-7-lesson-3-ex-06","version":"0.1.0","metadata":{"title":"Dates and yes/no values","status":"available","summary":"Use date for a calendar day and Boolean for a yes/no fact.","href":null,"difficulty":"standard","familyId":"week-7-lesson-3-ex-06","estimatedDurationMinutes":4,"activityType":"Classification","topics":["Data types"],"detail":"Use date for a calendar day and Boolean for a yes/no fact."},"relationships":{"learningOutcomes":["lo1","w7-process-erd","w7-interface-algo","w7-data"],"assignment":"os-formative","questions":[],"assets":[],"prerequisites":[]},"blocks":[{"schema":"lp.content.block","schemaVersion":"0.1.0","id":"week-7-lesson-3-ex-06-db","version":"0.1.0","metadata":{},"relationships":{},"type":"classification","content":{"formative":true,"questionId":"week-7-lesson-3-ex-06:db","sourceQuestionId":"db","prompt":"Choose a type.","categories":[{"id":"date","label":"Date"},{"id":"bool","label":"Boolean"},{"id":"bad","label":"Unsuitable"}],"items":[{"id":"item-1","label":"sessionDate","correctCategoryId":"date"},{"id":"item-2","label":"present (the learner attended or did not)","correctCategoryId":"bool"},{"id":"item-3","label":"Storing present as a 500-character essay","correctCategoryId":"bad"},{"id":"item-4","label":"requestedOn, the day the booking was made","correctCategoryId":"date"},{"id":"item-5","label":"Storing sessionDate as true or false","correctCategoryId":"bad"}],"feedback":{"correct":"A session happens on a date. Present is yes or no. An essay and a Boolean date are the wrong types.","incorrect":"Boolean has two states. It is a poor way to store a calendar day."}}}]},{"schema":"lp.content.activity","schemaVersion":"0.1.0","id":"week-7-lesson-3-ex-07","version":"0.1.0","metadata":{"title":"Field length","status":"available","summary":"Length should fit the real value and reject accidents.","href":null,"difficulty":"standard","familyId":"week-7-lesson-3-ex-07","estimatedDurationMinutes":3,"activityType":"Single choice","topics":["Field length"],"detail":"Length should fit the real value and reject accidents."},"relationships":{"learningOutcomes":["lo1","w7-process-erd","w7-interface-algo","w7-data"],"assignment":"os-formative","questions":[],"assets":[],"prerequisites":[]},"blocks":[{"schema":"lp.content.block","schemaVersion":"0.1.0","id":"week-7-lesson-3-ex-07-len","version":"0.1.0","metadata":{},"relationships":{},"type":"single-choice","content":{"formative":true,"questionId":"week-7-lesson-3-ex-07:len","sourceQuestionId":"len","sourceType":"single","prompt":"Booking status is only Confirmed or Cancelled. Which field design fits?","options":[{"id":"a","label":"Text of 2,000 characters, accepting any wording"},{"id":"b","label":"Short text, long enough for those words, with only those values allowed"},{"id":"c","label":"Length 1, so neither word can be stored"},{"id":"d","label":"A whole number, treating status as a count of bookings"}],"correctOptionId":"b","feedback":{"correct":"Give the field room for Confirmed and Cancelled, and list those allowed values. Course full is a message, not a third status.","incorrect":"An open 2,000-character field will collect other words. Length 1 cannot store Confirmed. A count is maxPlaces, not status."}}}]},{"schema":"lp.content.activity","schemaVersion":"0.1.0","id":"week-7-lesson-3-ex-08","version":"0.1.0","metadata":{"title":"Primary key in the dictionary","status":"available","summary":"The dictionary should say which field identifies the row.","href":null,"difficulty":"standard","familyId":"week-7-lesson-3-ex-08","estimatedDurationMinutes":3,"activityType":"Single choice","topics":["Primary keys"],"detail":"The dictionary should say which field identifies the row."},"relationships":{"learningOutcomes":["lo1","w7-process-erd","w7-interface-algo","w7-data"],"assignment":"os-formative","questions":[],"assets":[],"prerequisites":[]},"blocks":[{"schema":"lp.content.block","schemaVersion":"0.1.0","id":"week-7-lesson-3-ex-08-pk","version":"0.1.0","metadata":{},"relationships":{},"type":"single-choice","content":{"formative":true,"questionId":"week-7-lesson-3-ex-08:pk","sourceQuestionId":"pk","sourceType":"single","prompt":"In a data dictionary for Attendance, which field should be marked as the primary key?","options":[{"id":"a","label":"present"},{"id":"b","label":"room, copied from Session"},{"id":"c","label":"The learner's surname"},{"id":"d","label":"attendanceId"}],"correctOptionId":"d","feedback":{"correct":"attendanceId identifies one attendance row. present, room and surname can all repeat.","incorrect":"A yes/no value is not an identifier. Copying room onto Attendance also duplicates Session."}}}]},{"schema":"lp.content.activity","schemaVersion":"0.1.0","id":"week-7-lesson-3-ex-09","version":"0.1.0","metadata":{"title":"Foreign key in the dictionary","status":"available","summary":"Name the field and the entity it points at.","href":null,"difficulty":"standard","familyId":"week-7-lesson-3-ex-09","estimatedDurationMinutes":3,"activityType":"Single choice","topics":["Foreign keys"],"detail":"Name the field and the entity it points at."},"relationships":{"learningOutcomes":["lo1","w7-process-erd","w7-interface-algo","w7-data"],"assignment":"os-formative","questions":[],"assets":[],"prerequisites":[]},"blocks":[{"schema":"lp.content.block","schemaVersion":"0.1.0","id":"week-7-lesson-3-ex-09-fk","version":"0.1.0","metadata":{},"relationships":{},"type":"single-choice","content":{"formative":true,"questionId":"week-7-lesson-3-ex-09:fk","sourceQuestionId":"fk","sourceType":"single","prompt":"Attendance must record which session the register line is for. Which dictionary entry is right?","options":[{"id":"a","label":"sessionId, primary key of Attendance"},{"id":"b","label":"present, foreign key, references Course.title"},{"id":"c","label":"sessionId, foreign key, references Session"},{"id":"d","label":"No foreign key. Copy the session date and room into every attendance row"}],"correctOptionId":"c","feedback":{"correct":"sessionId on Attendance references Session.sessionId. attendanceId remains the primary key of Attendance.","incorrect":"Copying the session date and room duplicates Session. present is a Boolean, not a key."}}}]},{"schema":"lp.content.activity","schemaVersion":"0.1.0","id":"week-7-lesson-3-ex-10","version":"0.1.0","metadata":{"title":"Dictionary columns","status":"available","summary":"A developer needs more than a field name.","href":null,"difficulty":"standard","familyId":"week-7-lesson-3-ex-10","estimatedDurationMinutes":4,"activityType":"Matching","topics":["Data dictionary"],"detail":"A developer needs more than a field name."},"relationships":{"learningOutcomes":["lo1","w7-process-erd","w7-interface-algo","w7-data"],"assignment":"os-formative","questions":[],"assets":[],"prerequisites":[]},"blocks":[{"schema":"lp.content.block","schemaVersion":"0.1.0","id":"week-7-lesson-3-ex-10-cols","version":"0.1.0","metadata":{},"relationships":{},"type":"drag-drop","content":{"formative":true,"questionId":"week-7-lesson-3-ex-10:cols","sourceQuestionId":"cols","prompt":"Match each dictionary column to the question it answers.","items":[{"id":"type","label":"Data type"},{"id":"key","label":"Key"},{"id":"rule","label":"Validation rule"},{"id":"err","label":"Error message"}],"targets":[{"id":"m-type","label":"What kind of value is stored?"},{"id":"m-key","label":"Does this field identify the row, or point at another entity?"},{"id":"m-rule","label":"What must be true before the value is accepted?"},{"id":"m-err","label":"What should the user read if the value is rejected?"}],"correct":{"type":"m-type","key":"m-key","rule":"m-rule","err":"m-err"},"feedback":{"correct":"Type, key, rule and message answer different questions. A dictionary that only lists names is incomplete.","incorrect":"An error message is for the user. It is not the data type."}}}]},{"schema":"lp.content.activity","schemaVersion":"0.1.0","id":"week-7-lesson-3-ex-11","version":"0.1.0","metadata":{"title":"Names a developer can follow","status":"available","summary":"Pick one style and use it for every field.","href":null,"difficulty":"standard","familyId":"week-7-lesson-3-ex-11","estimatedDurationMinutes":3,"activityType":"Single choice","topics":["Naming"],"detail":"Pick one style and use it for every field."},"relationships":{"learningOutcomes":["lo1","w7-process-erd","w7-interface-algo","w7-data"],"assignment":"os-formative","questions":[],"assets":[],"prerequisites":[]},"blocks":[{"schema":"lp.content.block","schemaVersion":"0.1.0","id":"week-7-lesson-3-ex-11-name","version":"0.1.0","metadata":{},"relationships":{},"type":"single-choice","content":{"formative":true,"questionId":"week-7-lesson-3-ex-11:name","sourceQuestionId":"name","sourceType":"single","prompt":"Which set of names is the most consistent for this design?","options":[{"id":"a","label":"L, C, S and R, with the meanings kept in a separate note"},{"id":"b","label":"learnerId, courseId, sessionDate, requestedOn"},{"id":"c","label":"Learner-ID, course id, SessionDate and req"},{"id":"d","label":"Name, Name2, Name3 and Name4, in a fixed column order"}],"correctOptionId":"b","feedback":{"correct":"One style, full words and no spaces. Another developer can read the names without a private list.","incorrect":"Mixed punctuation, single letters and repeated Name all force the reader to guess."}}}]},{"schema":"lp.content.activity","schemaVersion":"0.1.0","id":"week-7-lesson-3-ex-12","version":"0.1.0","metadata":{"title":"Required or optional","status":"available","summary":"Required means the row is not valid without it.","href":null,"difficulty":"standard","familyId":"week-7-lesson-3-ex-12","estimatedDurationMinutes":4,"activityType":"Classification","topics":["Required fields"],"detail":"Required means the row is not valid without it."},"relationships":{"learningOutcomes":["lo1","w7-process-erd","w7-interface-algo","w7-data"],"assignment":"os-formative","questions":[],"assets":[],"prerequisites":[]},"blocks":[{"schema":"lp.content.block","schemaVersion":"0.1.0","id":"week-7-lesson-3-ex-12-req","version":"0.1.0","metadata":{},"relationships":{},"type":"classification","content":{"formative":true,"questionId":"week-7-lesson-3-ex-12:req","sourceQuestionId":"req","prompt":"For a booking request, classify each field.","categories":[{"id":"req","label":"Required"},{"id":"opt","label":"Optional"}],"items":[{"id":"item-1","label":"courseId","correctCategoryId":"req"},{"id":"item-2","label":"learnerId","correctCategoryId":"req"},{"id":"item-3","label":"phone, if email is already required","correctCategoryId":"opt"},{"id":"item-4","label":"status","correctCategoryId":"req"},{"id":"item-5","label":"A note about access arrangements the learner may choose to give","correctCategoryId":"opt"}],"feedback":{"correct":"A booking without a learner or a course is meaningless. Phone and access notes can be blank. Status is needed so staff can tell confirmed from full.","incorrect":"Do not make every column required. Do not leave the course optional."}}}]},{"schema":"lp.content.activity","schemaVersion":"0.1.0","id":"week-7-lesson-3-ex-13","version":"0.1.0","metadata":{"title":"Why validate","status":"available","summary":"Validation stops impossible data before it is stored.","href":null,"difficulty":"standard","familyId":"week-7-lesson-3-ex-13","estimatedDurationMinutes":3,"activityType":"Single choice","topics":["Validation"],"detail":"Validation stops impossible data before it is stored."},"relationships":{"learningOutcomes":["lo1","w7-process-erd","w7-interface-algo","w7-data"],"assignment":"os-formative","questions":[],"assets":[],"prerequisites":[]},"blocks":[{"schema":"lp.content.block","schemaVersion":"0.1.0","id":"week-7-lesson-3-ex-13-why","version":"0.1.0","metadata":{},"relationships":{},"type":"single-choice","content":{"formative":true,"questionId":"week-7-lesson-3-ex-13:why","sourceQuestionId":"why","sourceType":"single","prompt":"Why validate email and courseId when a place is requested?","options":[{"id":"a","label":"To recheck the live database later. That later check is verification, not this validation"},{"id":"b","label":"To reject a missing email or a courseId that is not a real course before a booking is stored"},{"id":"c","label":"To use the email as bookingId, so a separate primary key is unnecessary"},{"id":"d","label":"To stop the screen from showing an error message"}],"correctOptionId":"b","feedback":{"correct":"Validation rejects missing or impossible values before they are stored. The learner still needs a message that says what to correct.","incorrect":"Checking again after go-live is a different activity. An email can change and can be shared, so it is a poor primary key."}}}]},{"schema":"lp.content.activity","schemaVersion":"0.1.0","id":"week-7-lesson-3-ex-14","version":"0.1.0","metadata":{"title":"Range, format, presence","status":"available","summary":"Name the check correctly so the developer builds the right one.","href":null,"difficulty":"standard","familyId":"week-7-lesson-3-ex-14","estimatedDurationMinutes":5,"activityType":"Classification","topics":["Validation"],"detail":"Name the check correctly so the developer builds the right one."},"relationships":{"learningOutcomes":["lo1","w7-process-erd","w7-interface-algo","w7-data"],"assignment":"os-formative","questions":[],"assets":[],"prerequisites":[]},"blocks":[{"schema":"lp.content.block","schemaVersion":"0.1.0","id":"week-7-lesson-3-ex-14-checks","version":"0.1.0","metadata":{},"relationships":{},"type":"classification","content":{"formative":true,"questionId":"week-7-lesson-3-ex-14:checks","sourceQuestionId":"checks","prompt":"What kind of check is each rule?","categories":[{"id":"presence","label":"Presence"},{"id":"format","label":"Format"},{"id":"range","label":"Range"},{"id":"lookup","label":"Lookup"}],"items":[{"id":"item-1","label":"courseId must be entered","correctCategoryId":"presence"},{"id":"item-2","label":"Email must contain @ and a domain","correctCategoryId":"format"},{"id":"item-3","label":"maxPlaces must be from 1 to 40","correctCategoryId":"range"},{"id":"item-4","label":"courseId must match an existing course","correctCategoryId":"lookup"},{"id":"item-5","label":"sessionDate must be a real calendar date","correctCategoryId":"format"}],"feedback":{"correct":"Presence means it cannot be blank. Format means the shape of the value. Range means lowest and highest. Lookup means the value must already exist.","incorrect":"A date check is about the shape of a date, not about whether the course exists."}}}]},{"schema":"lp.content.activity","schemaVersion":"0.1.0","id":"week-7-lesson-3-ex-15","version":"0.1.0","metadata":{"title":"Missing information","status":"available","summary":"Decide what the system should do when a required value is absent.","href":null,"difficulty":"standard","familyId":"week-7-lesson-3-ex-15","estimatedDurationMinutes":4,"activityType":"Single choice","topics":["Missing data"],"detail":"Decide what the system should do when a required value is absent."},"relationships":{"learningOutcomes":["lo1","w7-process-erd","w7-interface-algo","w7-data"],"assignment":"os-formative","questions":[],"assets":[],"prerequisites":[]},"blocks":[{"schema":"lp.content.block","schemaVersion":"0.1.0","id":"week-7-lesson-3-ex-15-miss","version":"0.1.0","metadata":{},"relationships":{},"type":"single-choice","content":{"formative":true,"questionId":"week-7-lesson-3-ex-15:miss","sourceQuestionId":"miss","sourceType":"single","prompt":"The learner submits a request with no course selected. What should happen?","options":[{"id":"a","label":"Store Confirmed with a blank courseId and correct it later"},{"id":"b","label":"Do not store a booking. Ask the learner to choose a course"},{"id":"c","label":"Store the booking against the first course in the list"},{"id":"d","label":"Create an attendance row for every session of every course"}],"correctOptionId":"b","feedback":{"correct":"A booking without a course cannot be used. Stop, and ask for the missing course.","incorrect":"A blank courseId, or a guessed course, records the wrong request. Attendance belongs to a session the learner actually has."}}}]},{"schema":"lp.content.activity","schemaVersion":"0.1.0","id":"week-7-lesson-3-ex-16","version":"0.1.0","metadata":{"title":"Error messages","status":"available","summary":"Say what is wrong and what to do. Do not blame the learner with a code.","href":null,"difficulty":"standard","familyId":"week-7-lesson-3-ex-16","estimatedDurationMinutes":3,"activityType":"Single choice","topics":["Error messages"],"detail":"Say what is wrong and what to do. Do not blame the learner with a code."},"relationships":{"learningOutcomes":["lo1","w7-process-erd","w7-interface-algo","w7-data"],"assignment":"os-formative","questions":[],"assets":[],"prerequisites":[]},"blocks":[{"schema":"lp.content.block","schemaVersion":"0.1.0","id":"week-7-lesson-3-ex-16-err","version":"0.1.0","metadata":{},"relationships":{},"type":"single-choice","content":{"formative":true,"questionId":"week-7-lesson-3-ex-16:err","sourceQuestionId":"err","sourceType":"single","prompt":"The email address was left blank. Which message is most suitable?","options":[{"id":"a","label":"Error 500"},{"id":"b","label":"Invalid"},{"id":"c","label":"Enter an email address. Oakfield uses it to send the result of this request"},{"id":"d","label":"Validation rule 14 failed"}],"correctOptionId":"c","feedback":{"correct":"Name the field and why it is needed, in words the learner can act on.","incorrect":"A code, the word Invalid, or a rule number does not say what to type."}}}]},{"schema":"lp.content.activity","schemaVersion":"0.1.0","id":"week-7-lesson-3-ex-17","version":"0.1.0","metadata":{"title":"Check against a functional requirement","status":"available","summary":"The dictionary has to make the requirement possible.","href":null,"difficulty":"standard","familyId":"week-7-lesson-3-ex-17","estimatedDurationMinutes":8,"activityType":"Written response","topics":["Acceptance"],"detail":"The dictionary has to make the requirement possible."},"relationships":{"learningOutcomes":["lo1","w7-process-erd","w7-interface-algo","w7-data"],"assignment":"os-formative","questions":[],"assets":[],"prerequisites":[]},"blocks":[{"schema":"lp.content.block","schemaVersion":"0.1.0","id":"week-7-lesson-3-ex-17-fr","version":"0.1.0","metadata":{},"relationships":{},"type":"paragraph","content":{"text":"Functional requirement: a tutor can record, for one session, which booked learners were present."}},{"schema":"lp.content.block","schemaVersion":"0.1.0","id":"week-7-lesson-3-ex-17-check","version":"0.1.0","metadata":{},"relationships":{},"type":"short-response","content":{"formative":true,"questionId":"week-7-lesson-3-ex-17:check","sourceQuestionId":"check","prompt":"Say whether Learner, Course, Session, Booking and Attendance can meet that requirement. Name the fields a developer must have, and one validation rule that protects the register.","placeholder":"Meets the requirement? ...\nFields needed: ...\nWhy Booking is still needed: ...\nValidation: ...\nIf something is missing: ...","guidance":"Attendance needs sessionId and learnerId. Booking shows who was expected on the course. present is Boolean and should not be blank. Do not copy the room onto Attendance.","minChars":90}}]},{"schema":"lp.content.activity","schemaVersion":"0.1.0","id":"week-7-lesson-3-ex-18","version":"0.1.0","metadata":{"title":"Data dictionary for the Oakfield solution","status":"available","summary":"Refine the ERD if you need to, then write a dictionary another developer could build.","href":null,"difficulty":"standard","familyId":"week-7-lesson-3-ex-18","estimatedDurationMinutes":15,"activityType":"Written response","topics":["Data dictionary","ERD"],"detail":"Refine the ERD if you need to, then write a dictionary another developer could build."},"relationships":{"learningOutcomes":["lo1","w7-process-erd","w7-interface-algo","w7-data"],"assignment":"os-formative","questions":[],"assets":[],"prerequisites":[]},"blocks":[{"schema":"lp.content.block","schemaVersion":"0.1.0","id":"week-7-lesson-3-ex-18-task","version":"0.1.0","metadata":{},"relationships":{},"type":"paragraph","content":{"text":"Using your Lesson 1 ERD, write a data dictionary for Booking and Attendance. If that drawing is missing a key or a relationship, change the file and submit the updated diagram separately. Do not add card payments. Course full is a message, not a booking status."}},{"schema":"lp.content.block","schemaVersion":"0.1.0","id":"week-7-lesson-3-ex-18-dict","version":"0.1.0","metadata":{},"relationships":{},"type":"short-response","content":{"formative":true,"questionId":"week-7-lesson-3-ex-18:dict","sourceQuestionId":"dict","prompt":"For each field include name, entity, type, length or allowed values, key, required or optional, validation, and the error message. Note one ERD change, or say no change, and name the file if you updated it.","placeholder":"Booking fields:\n...\nAttendance fields:\n...\nERD change: ...\nUpdated file, if any: ...","guidance":"Include bookingId, learnerId, courseId, status (Confirmed or Cancelled) and requestedOn. Include attendanceId, sessionId, learnerId and present. Foreign keys must name the entity they reference.","minChars":160}}]},{"schema":"lp.content.activity","schemaVersion":"0.1.0","id":"week-7-homework-critique","version":"0.1.0","metadata":{"title":"Homework: critique a public screen","status":"available","summary":"Critique one public website or app screen against a user need and suggest one interface improvement.","href":null,"difficulty":"standard","familyId":"week-7-homework-critique","estimatedDurationMinutes":20,"activityType":"Independent study","topics":["Interface","User needs"],"detail":"Critique one public website or app screen against a user need and suggest one interface improvement."},"relationships":{"learningOutcomes":["lo1","w7-process-erd","w7-interface-algo","w7-data"],"assignment":"os-formative","questions":[],"assets":[],"prerequisites":[]},"blocks":[{"schema":"lp.content.block","schemaVersion":"0.1.0","id":"week-7-homework-critique-title","version":"0.1.0","metadata":{},"relationships":{},"type":"heading","content":{"text":"Independent study","level":2}},{"schema":"lp.content.block","schemaVersion":"0.1.0","id":"week-7-homework-critique-intro","version":"0.1.0","metadata":{},"relationships":{},"type":"paragraph","content":{"text":"Choose one public screen you can look at again, such as a college course page or a booking form. Judge it as an interface design, not as a brand review."}},{"schema":"lp.content.block","schemaVersion":"0.1.0","id":"week-7-homework-critique-screen","version":"0.1.0","metadata":{},"relationships":{},"type":"short-response","content":{"formative":true,"questionId":"week-7-homework-critique:screen","sourceQuestionId":"screen","prompt":"Name the screen and the user need you judged it against.","placeholder":"Screen: ... Need: ...","guidance":"The need should be a job the person is trying to finish.","minChars":30}},{"schema":"lp.content.block","schemaVersion":"0.1.0","id":"week-7-homework-critique-improve","version":"0.1.0","metadata":{},"relationships":{},"type":"short-response","content":{"formative":true,"questionId":"week-7-homework-critique:improve","sourceQuestionId":"improve","prompt":"What works, what gets in the way, and one change a developer could make? Use labels, the main action, navigation, or the message when something goes wrong.","placeholder":"Works: ... Gets in the way: ... Change: ... Who it helps: ...","guidance":"One specific change is enough. A colour preference is not a design change.","minChars":50}}]}]$w7act$;
  v_session_lists jsonb := $w7ses${"week-7-lesson-1":["week-7-lesson-1-ex-01","week-7-lesson-1-ex-02","week-7-lesson-1-ex-03","week-7-lesson-1-ex-04","week-7-lesson-1-ex-05","week-7-lesson-1-ex-06","week-7-lesson-1-ex-07","week-7-lesson-1-ex-08","week-7-lesson-1-ex-09","week-7-lesson-1-ex-10","week-7-lesson-1-ex-11","week-7-lesson-1-ex-12","week-7-lesson-1-ex-13","week-7-lesson-1-ex-14","week-7-lesson-1-ex-15","week-7-lesson-1-ex-16","week-7-lesson-1-ex-17","week-7-lesson-1-ex-18"],"week-7-lesson-2":["week-7-lesson-2-ex-01","week-7-lesson-2-ex-02","week-7-lesson-2-ex-03","week-7-lesson-2-ex-04","week-7-lesson-2-ex-05","week-7-lesson-2-ex-06","week-7-lesson-2-ex-07","week-7-lesson-2-ex-08","week-7-lesson-2-ex-09","week-7-lesson-2-ex-10","week-7-lesson-2-ex-11","week-7-lesson-2-ex-12","week-7-lesson-2-ex-13","week-7-lesson-2-ex-14","week-7-lesson-2-ex-15","week-7-lesson-2-ex-16","week-7-lesson-2-ex-17","week-7-lesson-2-ex-18"],"week-7-lesson-3":["week-7-lesson-3-ex-01","week-7-lesson-3-ex-02","week-7-lesson-3-ex-03","week-7-lesson-3-ex-04","week-7-lesson-3-ex-05","week-7-lesson-3-ex-06","week-7-lesson-3-ex-07","week-7-lesson-3-ex-08","week-7-lesson-3-ex-09","week-7-lesson-3-ex-10","week-7-lesson-3-ex-11","week-7-lesson-3-ex-12","week-7-lesson-3-ex-13","week-7-lesson-3-ex-14","week-7-lesson-3-ex-15","week-7-lesson-3-ex-16","week-7-lesson-3-ex-17","week-7-lesson-3-ex-18"],"week-7-homework":["week-7-homework-critique"]}$w7ses$;
  v_hash text;
  v_publication_id uuid;
  v_prev text;
  v_publisher uuid;
  v_staff_ref text;
  v_target text := '0.4.47';
  v_kept jsonb;
  v_sessions jsonb;
begin
  select coalesce(
    (select id from auth.users where id = 'fd5fcbfc-5c01-4df3-a8df-458e1dbb0cc4'::uuid),
    (select id from auth.users order by created_at nulls last, id limit 1)
  ) into v_publisher;

  if v_publisher is null then
    raise exception using errcode = 'P0001', message = 'Week 7 publication refused: no auth user';
  end if;

  select package_version into v_prev
  from platform.curriculum_publications
  where hub_code = 'tlevel-software-development'
    and course_key = 't-level-digital-software-development'
    and status = 'published';

  if v_prev is distinct from '0.4.46' then
    raise exception using errcode = 'P0001',
      message = format('Week 7 publication refused: expected published 0.4.46, found %s', coalesce(v_prev, 'none'));
  end if;

  if exists (
    select 1 from platform.curriculum_publications
    where hub_code = 'tlevel-software-development'
      and course_key = 't-level-digital-software-development'
      and package_version = v_target
  ) then
    raise notice 'T Level 0.4.47 already published';
    return;
  end if;

  select package into v_package
  from platform.curriculum_publications
  where hub_code = 'tlevel-software-development'
    and course_key = 't-level-digital-software-development'
    and status = 'published';

  select coalesce(jsonb_agg(activity order by ordinality), '[]'::jsonb)
  into v_kept
  from jsonb_array_elements(v_package->'activities') with ordinality as src(activity, ordinality)
  where activity->>'id' not like 'week-7-%';

  v_package := jsonb_set(v_package, '{activities}', v_kept || v_new_activities, true);

  select coalesce(jsonb_agg(
    case
      when session->>'id' like 'week-7%' then
        jsonb_set(
          session,
          '{relationships,activities}',
          coalesce(v_session_lists->(session->>'id'), '[]'::jsonb),
          true
        )
      else session
    end
    order by ordinality
  ), '[]'::jsonb)
  into v_sessions
  from jsonb_array_elements(v_package->'sessions') with ordinality as src(session, ordinality);

  v_package := jsonb_set(v_package, '{sessions}', v_sessions, true);

  v_package := jsonb_set(
    v_package,
    '{weeks}',
    (
      select coalesce(jsonb_agg(
        case
          when week->>'id' = 'week-7' then
            jsonb_set(week, '{metadata,status}', '"available"'::jsonb, true)
          else week
        end
        order by ordinality
      ), '[]'::jsonb)
      from jsonb_array_elements(v_package->'weeks') with ordinality as src(week, ordinality)
    ),
    true
  );

  v_package := jsonb_set(v_package, '{version}', '"0.4.47"'::jsonb, true);

  if (
    select count(*) from jsonb_array_elements(v_package->'activities') activity
    where activity->>'id' like 'week-7-%'
  ) <> 55 then
    raise exception using errcode = 'P0001', message = 'Week 7 publication refused: activity count is not 55';
  end if;

  if exists (
    select 1
    from jsonb_array_elements(v_package->'weeks') week
    where week->>'id' in ('week-1','week-2','week-3','week-4','week-5','week-6','week-7')
      and week->'metadata'->>'status' is distinct from 'available'
  ) then
    raise exception using errcode = 'P0001', message = 'Week 7 publication refused: weeks 1-7 must stay available';
  end if;

  perform platform.validate_curriculum_package(v_package);

  v_staff_ref := 'PLATFORM-ADMIN-' || upper(replace(v_publisher::text, '-', ''));
  v_hash := encode(extensions.digest(v_package::text, 'sha256'), 'hex');

  update platform.curriculum_publications
  set status = 'superseded'
  where hub_code = 'tlevel-software-development'
    and course_key = 't-level-digital-software-development'
    and status = 'published';

  insert into platform.curriculum_publications (
