    status, package, content_hash, author, reviewer, publication_notes,
    published_by_auth_user_id, published_by_staff_reference
  ) values (
    'tlevel-software-development',
    't-level-digital-software-development',
    v_target,
    '0.1.0',
    '0.1.0',
    'published',
    v_package,
    v_hash,
    'T Level Week 7 publication',
    'Curriculum review',
    'Publish 55 Week 7 exercises for marking. Weeks 1-7 stay available. Previous version 0.4.46.',
    v_publisher,
    v_staff_ref
  )
  returning id into v_publication_id;

  perform platform.project_curriculum_package(
    v_package,
    'tlevel-software-development',
    't-level-digital-software-development',
    v_target,
    v_publication_id
  );
